 [('Capital is at ___ . (risk)','risk','fórmula.',None),('Past performance is not a reliable ___ to future returns. (guide)','guide','aviso.',None),('The value can fall as well as ___ . (rise)','rise','fórmula.',None),('Use of the wrapper is subject ___ annual limits. (to)','to','preposição.',None)],
